import{c as o,Z as e,Q as r,j as i,m as l,o as u}from"./chunks/framework.DOi4mjdC.js";const _=JSON.parse('{"title":"天净沙·秋思","description":"","frontmatter":{"title":"天净沙·秋思","author":"马致远","dynasty":"元"},"headers":[],"relativePath":"books/shici/yuanqu/1.md","filePath":"books/shici/yuanqu/1.md"}'),n={name:"books/shici/yuanqu/1.md"};function s(h,a,q,c,d,p){const t=e("PoemNav");return r(),i("div",null,[a[0]||(a[0]=l('<h1 id="天净沙·秋思" tabindex="-1">天净沙·秋思 <a class="header-anchor" href="#天净沙·秋思" aria-label="Permalink to &quot;天净沙·秋思&quot;">​</a></h1><p><strong>[元] <a href="/authors/mazhiyuan.html">马致远</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>枯藤老树昏鸦，小桥流水人家，古道西风瘦马。 夕阳西下，断肠人在天涯。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>枯藤：枯萎的枝蔓</li><li>昏鸦：黄昏时归巢的乌鸦</li><li>古道：古老荒凉的道路</li><li>西风：秋风</li><li>瘦马：瘦骨如柴的马</li><li>断肠人：形容伤心悲痛到极点的人，此处指漂泊天涯、极度忧伤的旅人</li><li>天涯：天边，指远离家乡的地方</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>枯藤缠绕着老树，树枝上栖息着黄昏时归巢的乌鸦。小桥下，流水潺潺，旁边有几户人家。在古老荒凉的道路上，秋风萧瑟，一匹疲惫的瘦马驮着游子前行。 夕阳向西缓缓落下，极度忧伤的旅人还漂泊在天涯海角。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首小令很短，一共只有五句二十八个字，全曲无一&quot;秋&quot;字，但却描绘出一幅凄凉动人的秋郊夕照图，并且准确地传达出旅人凄苦的心境。</p><p>这首小令前三句皆写景色，但这些景色都是情语，&quot;枯&quot;&quot;老&quot;&quot;昏&quot;&quot;瘦&quot;等字眼使浓郁的秋色之中蕴含着无限凄凉悲苦的情调。第一句&quot;枯藤老树昏鸦&quot;，就给人以萧瑟之感；第二句&quot;小桥流水人家&quot;，看似温馨的田园景象，却反衬出游子的孤独；第三句&quot;古道西风瘦马&quot;，更是将漂泊之苦推向极致。</p><p>最后两句&quot;夕阳西下，断肠人在天涯&quot;，点明主旨，将景与情完美融合。全曲语言凝练，意境深远，被后人誉为&quot;秋思之祖&quot;，是元曲中写景抒情的巅峰之作。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><blockquote><p><strong>马致远</strong>（约1250年－约1321年），号东篱，元代著名戏曲作家、散曲家，元曲四大家之一。其散曲风格豪放洒脱，意境深远。</p><p><a href="/authors/mazhiyuan.html">查看作者详情 →</a></p></blockquote>',15)),u(t)])}const b=o(n,[["render",s]]);export{_ as __pageData,b as default};
